"use server";
import { z } from "zod";
import { revalidatePath } from "next/cache";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/session";
import { requireEntitlement } from "@/lib/entitlements";
import { actionErrorDetails } from "@/lib/errors";
import { AppError, type ActionResult } from "@/lib/errors";
import type { Prisma } from "@/generated/prisma/client";

async function mutate(
  id: string,
  work: (
    tx: Prisma.TransactionClient,
    userId: string,
    id: string,
  ) => Promise<string>,
): Promise<ActionResult> {
  const user = await requireUser();
  try {
    const parsed = z.uuid().parse(id);
    const message = await db.$transaction(async (tx) => {
      await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${user.id} FOR UPDATE`;
      const active = await tx.user.findFirst({
        where: { id: user.id, deletionRequestedAt: null },
      });
      if (!active) throw new AppError("Account unavailable.");
      return work(tx, user.id, parsed);
    });
    for (const path of ["/history", "/contacts", "/compose"])
      revalidatePath(path);
    return { ok: true, message };
  } catch (error) {
    return {
      ok: false,
      ...(error instanceof AppError ? actionErrorDetails(error) : {}),
      message:
        error instanceof AppError
          ? error.message
          : "Could not save this change. Please try again.",
    };
  }
}
async function ownedSend(
  tx: Prisma.TransactionClient,
  userId: string,
  id: string,
) {
  const send = await tx.send.findFirst({
    where: { id, campaign: { userId }, historyDeletedAt: null },
  });
  if (!send) throw new AppError("Message not found.");
  return send;
}
export async function markReplied(id: string) {
  return mutate(id, async (tx, userId, sendId) => {
    await requireEntitlement(userId, "markReplied", tx);
    const send = await ownedSend(tx, userId, sendId);
    if (send.status !== "SENT" && send.status !== "REPLIED")
      throw new AppError("Only accepted messages can be marked replied.");
    await tx.send.updateMany({
      where: { id: sendId, campaign: { userId } },
      data: {
        status: "REPLIED",
        replyMarkedAt: send.replyMarkedAt ?? new Date(),
      },
    });
    await tx.contact.updateMany({
      where: { id: send.contactId, userId },
      data: { followUpRequestedAt: null },
    });
    return "Reply marked manually.";
  });
}

export async function undoReply(id: string) {
  return mutate(id, async (tx, userId, sendId) => {
    await requireEntitlement(userId, "markReplied", tx);
    const send = await ownedSend(tx, userId, sendId);
    if (send.status === "SENT") return "Reply mark already removed.";
    if (send.status !== "REPLIED")
      throw new AppError("Only replied messages can be undone.");
    await tx.send.updateMany({
      where: {
        id: sendId,
        campaign: { userId },
        historyDeletedAt: null,
        status: "REPLIED",
      },
      data: { status: "SENT", replyMarkedAt: null },
    });
    return "Reply mark removed.";
  });
}
